//! A few icons from the site's icon set (`openagents_ui::icons::Icon`),
//! as the inner markup of a 24 by 24 `svg.oa-icon`, so the step cards
//! look like the chat's tool-call cards without linking the UI crate.

/// An icon's `<svg>` at the small size, as the tool-call cards use.
#[must_use]
pub fn svg(inner: &str) -> String {
    format!(
        "<svg class=\"oa-icon\" data-size=\"sm\" aria-hidden=\"true\" focusable=\"false\" width=\"1em\" height=\"1em\" viewBox=\"0 0 24 24\" fill=\"currentColor\">{inner}</svg>"
    )
}

